    LANGUAGE_WRAPPER = 'Define a bi-restricted overpartition function O_{v,a,b}(n) as follows. An overpartition of n is a partition in which, for each part size m, the first occurrence may be overlined. In O_{v,a,b}(n), we impose residue-class restrictions modulo v: (i) if m ≡ a (mod v), non-overlined copies are forbidden and at most one overlined m may appear; (ii) if m ≡ b (mod v), overlined copies are forbidden while any number of non-overlined copies may appear; (iii) for all other m, the usual overpartition rule applies (any number of non-overlined copies, and optionally one overlined copy). The corresponding generating factor for each part size m is: 1 + q^m if m ≡ a (mod v); 1/(1 − q^m) if m ≡ b (mod v); and (1 + q^m)/(1 − q^m) otherwise. Let N = {alpha}·3^{2·{k}+1}·{n0} + ( {beta}·3^{2·{k}} − 1 )/4, and let M = 2^{ {t} }. Here v ≥ 3, a and b are distinct residues modulo v, and β ≡ 1 (mod 4) so that N is an integer. Compute O_{v,a,b}(N) modulo M. Report your answer as an integer in [0, M−1].'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Randomly generate parameters with constraints, ensuring tractable but non-trivial N
# and that a_residue != b_residue.
# We will repeatedly try until constraints are satisfied.
def pick_params():
    v = rng.choice([3, 5])
    a = rng.randrange(v)
    b = rng.randrange(v)
    while b == a:
        b = rng.randrange(v)
    t = rng.choice([7, 8])  # M in {128, 256}
    k = rng.randrange(0, 3)  # 0,1,2
    alpha = rng.choice([6, 18, 30])
    # beta must be 1 mod 4
    beta_candidates = list(range(1, 201, 4))
    rng.shuffle(beta_candidates)
    pow3_2k = 3 ** (2 * k)
    pow3_2k1 = 3 ** (2 * k + 1)
    for beta in beta_candidates:
        base = (beta * pow3_2k - 1) // 4
        # ensure integer
        if (beta * pow3_2k - 1) % 4 != 0:
            continue
        # Range for N
        Nmax = rng.choice([700, 800, 900, 1000, 1100, 1200])
        Nmin = rng.choice([120, 150, 180, 200])
        step = alpha * pow3_2k1
        # choose n0 so that N is in [Nmin, Nmax]
        if step <= 0:
            continue
        n0_min = max(0, (Nmin - base + step - 1) // step)
        n0_max = (Nmax - base) // step
        if n0_max < n0_min:
            continue
        # prefer a non-trivial n0
        n0 = rng.randrange(n0_min, n0_max + 1)
        N = alpha * pow3_2k1 * n0 + base
        if N < Nmin or N > Nmax:
            continue
        return {
            'v': v, 'a_residue': a, 'b_residue': b,
            'alpha': alpha, 'beta': beta,
            'k': k, 'n0': n0, 't': t, 'N': N
        }
    return None
params = None
for _ in range(100):
    params = pick_params()
    if params is not None:
        break
if params is None:
    # fallback deterministic params
    v = 3; a=0; b=1; t=7; k=1; alpha=18; beta=153
    pow3_2k = 3 ** (2 * k)
    pow3_2k1 = 3 ** (2 * k + 1)
    base = (beta * pow3_2k - 1) // 4
    n0=1
    N = alpha * pow3_2k1 * n0 + base
    params = {'v': v, 'a_residue': a, 'b_residue': b, 'alpha': alpha, 'beta': beta, 'k': k, 'n0': n0, 't': t, 'N': N}
# Now compute the answer modulo M via DP on generating function factors
v = params['v']; a = params['a_residue']; b = params['b_residue']
N = params['N']; M = 1 << params['t']
# DP: dp[s] = number of valid overpartitions to sum s modulo M
dp = [0] * (N + 1)
dp[0] = 1
for m in range(1, N + 1):
    r = m % v
    if r == a:
        # factor (1 + q^m)
        new_dp = dp[:]  # choose 0 copies
        for s in range(m, N + 1):
            new_dp[s] = (new_dp[s] + dp[s - m]) % M  # choose exactly one overlined copy
        dp = new_dp
    elif r == b:
        # factor 1/(1 - q^m): unbounded non-overlined
        for s in range(m, N + 1):
            dp[s] = (dp[s] + dp[s - m]) % M
    else:
        # factor (1 + q^m)/(1 - q^m): first unbounded, then one optional overlined
        # unbounded non-overlined
        for s in range(m, N + 1):
            dp[s] = (dp[s] + dp[s - m]) % M
        # then multiply by (1 + q^m)
        new_dp = dp[:]
        for s in range(m, N + 1):
            new_dp[s] = (new_dp[s] + dp[s - m]) % M
        dp = new_dp
ans = dp[N] % M
out = {
    'v': params['v'],
    'a_residue': params['a_residue'],
    'b_residue': params['b_residue'],
    'alpha': params['alpha'],
    'beta': params['beta'],
    'k': params['k'],
    'n0': params['n0'],
    't': params['t']
}
# The final answer is ans
out['_answer'] = ans
return out

